/**
 * The math shell string contract — the stored form an equation takes.
 *
 * Split from math.ts (which owns the KaTeX machinery) because the shell
 * builder is a pure string function with no katex dependency, and the
 * share viewer's markdown renderer (generated by scripts/build-share.mjs
 * from editor/markdown/render.ts) needs exactly this piece — bundling
 * math.ts would drag KaTeX and its stylesheet onto the no-build share
 * island. math.ts re-exports both members for its existing importers;
 * new code that only builds shells imports from here.
 */
import { escapeHtmlAttr } from '../lib/escape';

export const MATH_CLASS = 'padify-math';

/** The stored shell for a LaTeX equation (empty — rendered in the DOM). */
export function buildMathShell(latex: string): string {
  return `<span class="${MATH_CLASS}" data-latex="${escapeHtmlAttr(latex)}" contenteditable="false"></span>`;
}
